package fr.roadguard.app;
import android.app.Application;import android.content.*;import java.io.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={26,28,35},application=Application.class)
public class PhoneMapTilesRuntimeTest {
 Context app;PhoneMapTiles tiles;SharedPreferences prefs;byte[] png=DownloadedMapStore.TRANSPARENT;
 @Before public void setup()throws Exception{app=RuntimeEnvironment.getApplication();prefs=app.getSharedPreferences("MainActivity",0);prefs.edit().clear().putBoolean("phone_guidance_share",true).putBoolean("phone_map_share",true).commit();app.getSharedPreferences("roadguard_community",0).edit().putBoolean("approved",true).commit();tiles=new PhoneMapTiles(app);File f=new File(app.getFilesDir(),"tiles/3/4/2.png");f.getParentFile().mkdirs();try(FileOutputStream o=new FileOutputStream(f)){o.write(png);}}
 @Test public void exactInstalledRasterAndPrivateCatalog()throws Exception{JSONObject o=new JSONObject(tiles.info());assertTrue(o.getBoolean("enabled"));assertTrue(o.getBoolean("raster"));assertTrue(o.getString("catalog").matches("[a-f0-9]{64}"));assertArrayEquals(png,tiles.tile(o.getString("catalog"),"raster",3,4,2));}
 @Test public void missingDoesNotDownloadOrReadHttpCache(){assertNull(tiles.tile(tiles.catalog(),"raster",3,5,2));assertFalse(new File(app.getCacheDir(),"visible-tiles").exists());}
 @Test public void consentsAndApprovalRequired()throws Exception{prefs.edit().putBoolean("phone_map_share",false).commit();assertFalse(new JSONObject(tiles.info()).getBoolean("enabled"));assertNull(tiles.tile(tiles.catalog(),"raster",3,4,2));prefs.edit().putBoolean("phone_map_share",true).putBoolean("phone_guidance_share",false).commit();assertFalse(tiles.allowed());prefs.edit().putBoolean("phone_guidance_share",true).commit();app.getSharedPreferences("roadguard_community",0).edit().putBoolean("approved",false).commit();assertFalse(tiles.allowed());}
 @Test public void staleCatalogAndInvalidInputsCannotReadFiles(){String old=tiles.catalog();prefs.edit().putLong("phone_map_epoch",123).commit();assertNotEquals(old,tiles.catalog());assertNull(tiles.tile(old,"raster",3,4,2));assertNull(tiles.tile(tiles.catalog(),"../../secret",3,4,2));assertNull(tiles.tile(tiles.catalog(),"raster",3,8,2));assertNull(tiles.tile(tiles.catalog(),"vector",23,0,0));}
 @Test public void oversizedRasterNeverEntersBinder()throws Exception{File f=new File(app.getFilesDir(),"tiles/3/4/2.png");try(FileOutputStream o=new FileOutputStream(f)){o.write(png);o.write(new byte[PhoneMapTiles.MAX_BYTES]);}assertNull(tiles.tile(tiles.catalog(),"raster",3,4,2));}
}
